// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Arrange: fund contract with 1 ether, set up non-Owner attacker
        address attacker = address(0x1234);
        vm.deal(address(c), 1 ether);

        // Act: non-Owner calls Command with 0.5 ether
        bytes memory data = "";
        vm.prank(attacker);
        c.Command{value: 0.5 ether}(attacker, data);

        // Assert: original C would require Owner check, reverting for non-Owner
        // but mutant M removes require, executes call and potentially changes state.
        // In original, withdraw() would still check Owner, but in mutant it doesn't.
        // For this test, we observe that after the Command call (which in original reverts),
        // the contract balance in original remains 1 ether, in mutant it's 0.5 ether.
        // However, the original Command reverts, so attacker cannot change state.
        // Let's instead test that after Command, in mutant the contract balance changes.
        // Use try/catch to see if Commmand reverts (original) or succeeds (mutant).
        bool commandSucceeded;
        vm.prank(attacker);
        try c.Command{value: 0.5 ether}(attacker, data) {
            commandSucceeded = true;
        } catch {
            commandSucceeded = false;
        }

        // For reference: commandSucceeded should be false (require fails)
        // For mutant: commandSucceeded should be true (require removed)
        // Then after that, withdraw() effect differs.

        // But we need a single assertion that differs. Let's check contract balance.
        // In original, command failed -> balance unchanged (1 ether)
        // In mutant, command succeeded -> balance changed (sent 0.5 ether to attacker)
        // Actually, Command does: adr.call{value: msg.value}(data);
        // If attacker calls with attacker as adr, it sends 0.5 to attacker, contract keeps 0.5
        // So final balance in mutant = 0.5 ether, in original = 1 ether

        // However, after the try/catch, the second call may have already changed state.
        // Better: do the call once, then check balance.
        // Reset:
        c = new C();
        vm.deal(address(c), 1 ether);

        // Execute the call
        vm.prank(attacker);
        c.Command{value: 0.5 ether}(attacker, data);

        // In original contract, this would revert, leaving balance 1 ether
        // In mutant, it succeeds, leaving balance 0.5 ether
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == 0.5 ether, "Mutant should have 0.5 ether");
        // The original would have 1 ether, so this assertion passes on mutant, fails on original.
    }
}

