pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Non-owner calls Command with 0.5 ether (the msg.value sent)
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        c.Command{value: 0.5 ether}(nonOwner, "");

        // Check that owner can still withdraw (reference will revert for nonOwner, but owner can)
        // The buggy version would have already transferred all balance to nonOwner via withdraw
        address owner = c.Owner();
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        (bool successOwner, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        uint256 ownerBalanceAfter = owner.balance;

        // Reference: withdraw succeeds, Owner gets 1.5 ether total (initial 1 + 0.5 sent back)
        // Bug: contract already empty after nonOwner withdraw, Owner gets nothing
        assertTrue(ownerBalanceAfter - ownerBalanceBefore == 1.5 ether);
    }
}

