pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: non-Owner address
        address nonOwner = address(0x1234);
        // Give ether to the contract and to nonOwner
        vm.deal(address(c), 1 wei);
        vm.deal(nonOwner, 1 wei);

        // nonOwner calls Command with value 1 wei, sending to itself (no-op delegatecall? actually just sends to address(this) which is the contract, but the contract is the caller, so it's a no-op call)
        vm.prank(nonOwner);
        c.Command{value: 1 wei}(address(this), "");

        // Now try withdraw as nonOwner; wrap in try/catch to catch revert
        bool ok;
        vm.prank(nonOwner);
        try c.withdraw() { ok = true; } catch { ok = false; }

        // In the reference, withdraw() requires msg.sender == Owner, so nonOwner's call reverts => ok is false
        // In the buggy version, no require => ok is true, and balance is sent to Owner => contract balance becomes 0
        // Assert that ok is false (reference passes, bug fails because ok would be true)
        assertTrue(!ok);
    }
}

