pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: fund the contract with 1 ether using Command
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        c.Command{value: 1 ether}(address(0), "");
        // Record balance before multiplicate call
        uint256 balanceBefore = address(c).balance;
        // Call multiplicate with msg.value exactly equal to contract balance
        address recipient = address(0x1234);
        vm.deal(address(this), address(c).balance);
        vm.prank(address(this));
        // We'll use try/catch to check if it reverts
        bool ok = false;
        try c.multiplicate{value: address(c).balance}(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;
        // In the reference, it does not revert and balance becomes 0; in the bug, it reverts and balance stays same
        // So we assert that the reference behavior is: ok == true and balanceAfter == 0
        // For the bug, ok == false and balanceAfter == balanceBefore
        // We choose to assert that ok is true and balanceAfter is 0 (reference passes, bug fails)
        assertTrue(ok && balanceAfter == 0);
    }
}
